    'Con el plan' => 'With the plan',
    'Con el plan Profesional imprime el fixture completo de cada campeonato (con o sin resultados) y ve el esquema de todo el torneo desde el primer día: grupos, jornadas y la llave de la fase final con los cruces, que se llenan solos con los clasificados.' => 'With the Professional plan you can print the full fixtures of each championship (with or without results) and see the layout of the whole tournament from day one: groups, matchdays and the final-phase bracket with the pairings, which fill in automatically with the qualifiers.',
    'Con este enlace, cualquiera agrega todos los partidos del campeonato al calendario de su celular (y se actualiza solo). Cada equipo tiene el suyo en su página pública.' => 'With this link, anyone can add all the championship\'s matches to their phone\'s calendar (it updates automatically). Each team has its own on its public page.',
