    'Ej: traer el dobok limpio y el carnet' => 'E.g.: bring a clean dobok and ID card',
    'Ej: uniforme, inscripción a un torneo, viaje, seguro. Queda en la cuenta de cada alumno, aparte de la mensualidad.' => 'E.g.: uniform, tournament registration, trip, insurance. It stays on each student\'s account, separate from the monthly fee.',
    'Ej: volante mixto' => 'E.g.: box-to-box midfielder',
    'Ej: ya trota sin dolor; empieza trabajo con balón' => 'E.g.: now jogging without pain; starting work with the ball',
    'Ej: zurdo, rápido, buen primer toque, le cuesta el juego aéreo' => 'E.g.: left-footed, fast, good first touch, struggles in the air',
    'Ej: {n}' => 'E.g.: {n}',
    'Ej: {n} = al llegar a {n} amarillas se suspende. En básquet cuentan las faltas técnicas.' => 'E.g.: {n} = suspended upon reaching {n} yellow cards. In basketball, technical fouls count.',
    'Ej: {n} = en Sub-{n} se permite un pasado de hasta {n} años. {n} = sin límite.' => 'E.g.: {n} = in Under-{n}, one over-age player of up to {n} years is allowed. {n} = no limit.',
    'Ej: {n} = gana del primer año de cada liga. {n} = mientras la liga siga pagando.' => 'E.g.: {n} = earned only on each league\'s first year. {n} = for as long as the league keeps paying.',
    'Ej: {n} = partido al mejor de {n} sets.' => 'E.g.: {n} = best-of-{n} sets match.',
    'Ej: {n} = vence el {n} de cada mes.' => 'E.g.: {n} = due on the {n}th of each month.',
    'Ej: {n} a {n} cc' => 'E.g.: {n} to {n} cc',
    'Ej: {n} equipos' => 'E.g.: {n} teams',
