    'Ej: {n}. {n} = sin límite. La vocalía avisa cuando un jugador llega.' => 'E.g.: {n}. {n} = no limit. The scorekeeping flags when a player arrives.',
    'Ej: {n}/{n}/{n}. Sirve para la categoría Sub.' => 'E.g.: {n}/{n}/{n}. Used for the Under category.',
    'Ej: {n}er quimestre {n}' => 'E.g.: {n}st term {n}',
    'Ej: «en Finanzas» o «en la página pública de la liga».' => 'E.g.: “in Finance” or “on the league\'s public page”.',
    'Ej: «en un Excel» o «a mano en un cuaderno».' => 'E.g.: “in an Excel file” or “by hand in a notebook”.',
    'Ej: «hoy los delegados me mandan las fotos por WhatsApp y se me pierden».' => 'E.g.: “today the delegates send me the photos on WhatsApp and I lose them”.',
    'Ej: ¿Quién fue el mejor jugador de la final?' => 'E.g.: Who was the best player of the final?',
    'Ejemplo' => 'Example',
    'Ejemplo, sprint de 30 m (gana el menor), 10 a 11 años: amarillo desde 5,9 s y verde desde 5,4 s → 5,3 s es verde, 5,7 s es amarillo y 6,1 s es rojo.' => 'Example: 30 m sprint (lowest wins), ages 10 to 11: yellow from 5.9 s and green from 5.4 s → 5.3 s is green, 5.7 s is yellow and 6.1 s is red.',
    'Ejemplo:' => 'Example:',
    'Ejemplo: Escuela Completo (${n}) + Profesional (${n}) =' => 'Example: Complete School (${n}) + Professional (${n}) =',
