    'Ejercer mis derechos · Liga Demo TuAcademia' => 'Exercise my rights · Liga Demo TuAcademia',
    'Ejercer mis derechos · Liga Referida Test' => 'Exercise my rights · Liga Referida Test',
    'Ejercicio de la biblioteca' => 'Drill from the library',
