    'Ejercicios de la clase' => 'Class exercises',
    'El' => 'The',
    'El archivo está vacío: debe tener la fila de títulos y al menos una fila con datos.' => 'The file is empty: it must have the header row and at least one row of data.',
    'El archivo tiene más de' => 'The file has more than',
    'El arquero inicia con los defensores contra {n} o {n} delanteros que presionan; el objetivo es pasar la línea media con control.' => 'The goalkeeper starts with the defenders against {n} or {n} forwards who press; the goal is to cross the halfway line with control.',
    'El arquero inicia con los defensores contra {n} o {n} delanteros que presionan; el …' => 'The goalkeeper starts play with the defenders against {n} or {n} pressing forwards; the …',
    'El asistente' => 'The assistant',
    'El asistente nunca puede crear ni cambiar usuarios. Puede cambiar estos permisos cuando quiera; valen desde la siguiente página que abra.' => 'The assistant can never create or change users. You can change these permissions whenever you want; they apply from the next page they open.',
    'El cliente le escribe aquí para confirmar o pagar.' => 'The customer writes to you here to confirm or pay.',
    'El cobro con tarjeta se está terminando de conectar con Plux. Ya puede dejarlo configurado; el botón de pago aparecerá cuando esté listo.' => 'Card payments are being connected to Plux. You can set it up now; the payment button will appear when it is ready.',
    'El código' => 'The code',
    'El delegado sube la foto de su transferencia y el recibo sale al aprobarla.' => 'The delegate uploads a photo of their transfer and the receipt is issued once it is approved.',
    'El enlace' => 'The link',
    'El entrenador pasa desde afuera del área; el jugador controla orientado hacia el arco y remata en máximo 2 toques.' => 'The coach passes from outside the box; the player controls toward the goal and shoots in 2 touches at most.',
    'El equipo' => 'The team',
    'El examen está cerrado. Ábralo de nuevo para corregir resultados.' => 'The exam is closed. Reopen it to correct results.',
    'El examen está cerrado. Ábralo de nuevo para inscribir.' => 'The exam is closed. Reopen it to register students.',
    'El fixture completo de cada campeonato en PDF (con resultados o en blanco para llenar a mano) y el esquema de todo el torneo desde el primer día: grupos, jornadas y la llave de la fase final con los cruces (1° Grupo A vs 2° Grupo B), que se llenan solos con los clasificados.' => 'The full fixtures of each championship in PDF (with results or blank to fill in by hand) and the layout of the whole tournament from day one: groups, matchdays and the final-phase bracket with the pairings (1st Group A vs 2nd Group B), which fill in automatically with the qualifiers.',
    'El ganador de cada partido pasa solo a la siguiente ronda.' => 'The winner of each match advances automatically to the next round.',
    'El idioma con el que se abre su página para el público. Cada visitante (y cada usuario del panel) puede cambiarlo con el botón 🌐 de arriba.' => 'The language in which your page opens for the public. Each visitor (and each dashboard user) can change it with the 🌐 button at the top.',
    'El informe de desarrollo reúne la asistencia, los gráficos de tests (comparados con su categoría), la evaluación técnica, las insignias, las metas y el comentario del profesor del trimestre. La familia también lo ve en su portal y lo puede guardar en PDF.' => 'The development report brings together attendance, test charts (compared with their category), the technical evaluation, badges, goals and the coach\'s comment for the term. The family also sees it in their portal and can save it as a PDF.',
    'El informe del árbitro' => 'The referee\'s report',
    'El jugador autorizó' => 'The player authorized',
    'El jugador no insultó al árbitro; pedimos revisar el video.' => 'The player did not insult the referee; we ask for the video to be reviewed.',
    'El lector' => 'The reader',
    'El pago con tarjeta no se completó.' => 'The card payment was not completed.',
    'El perfil' => 'The profile',
    'El precio incluye' => 'The price includes',
    'El profesor dio la clase' => 'The coach taught the class',
    'El profesor planifica las clases por adelantado con la biblioteca de ejercicios de la escuela; cada clase guarda ejercicios, minutos, intensidad, fotos y una nota para cada alumno, y los padres ven el diario de entrenamientos de su hijo.' => 'The coach plans classes in advance with the school\'s exercise library; each class stores exercises, minutes, intensity, photos and a note for each student, and parents see their child\'s training diary.',
    'El profesor toma lista en segundos y anota el plan de la clase.' => 'The coach takes attendance in seconds and records the class plan.',
    'El público reserva sus canchas por horas desde el celular y el cobro entra a finanzas.' => 'The public books fields by the hour from their phones and the payment goes into finance.',
    'El público vota desde la página de la liga (pestaña' => 'The public votes from the league page (tab',
    'El que corresponda por su edad' => 'The one that corresponds to their age',
    'El que está en curso' => 'The one in progress',
    'El representante ve en su celular la asistencia, los pagos, las evaluaciones, la libreta y el carnet de sus hijos, y puede subir el comprobante de pago.' => 'On their phone, the guardian sees their children\'s attendance, payments, evaluations, report card and ID card, and can upload proof of payment.',
    'El semáforo de cada resultado sale solo:' => 'The traffic light for each result is set automatically:',
    'El sistema completo para administrar tu liga de fútbol' => 'The complete system to manage your football league',
    'El sistema completo para su escuela deportiva' => 'The complete system for your sports school',
    'El sistema le avisa por Telegram cuando alguien pide una demo, cuando a una demo le quedan {n} días (día {n}) y el día que vence (día {n}), con el mensaje de WhatsApp listo para enviar.' => 'The system notifies you via Telegram when someone requests a demo, when a demo has {n} days left (day {n}) and on the day it expires (day {n}), with the WhatsApp message ready to send.',
    'El sistema pone a cada alumno en su categoría por edad (Sub-{n}, Sub-{n}, Sub-{n}…) o en grupos abiertos.' => 'The system places each student in their age category (Under-{n}, Under-{n}, Under-{n}…) or in open groups.',
    'El sistema reparte horarios, canchas y árbitros sin choques, o lo hace usted a mano.' => 'The system distributes schedules, fields and referees without clashes, or you do it by hand.',
    'El sistema reparte los equipos al azar y puede generar el fixture de una vez.' => 'The system distributes the teams at random and can generate the fixtures right away.',
    'El sistema reparte los partidos en las canchas y horarios que usted indique, sin que un equipo o un árbitro tenga dos partidos a la vez, alternando a los equipos entre horarios temprano y tarde y repartiendo los partidos entre los árbitros. Primero ve la propuesta y luego decide si la guarda.' => 'The system distributes matches across the fields and times you indicate, without any team or referee having two matches at once, alternating teams between early and late slots and spreading matches among the referees. You first see the proposal and then decide whether to save it.',
    'El sistema suma lo que se le debe a cada árbitro por los partidos jugados, según su función (central, asistente, cuarto). El valor por partido se pone en cada campeonato:' => 'The system adds up what is owed to each referee for the matches played, according to their role (center, assistant, fourth official). The fee per match is set in each championship:',
    'El sistema ya está en inglés, francés, portugués e italiano: use el botón 🌐 de la barra de arriba. Elija el idioma de su página pública en Parámetros.' => 'The system is now available in English, French, Portuguese and Italian: use the 🌐 button in the top bar. Choose the language of your public page in Settings.',
    'El video pesa más de' => 'The video is larger than',
    'El vocal abre este enlace en su' => 'The scorekeeper opens this link on their',
    'El vocal escanea el carnet y ve la foto:' => 'The scorekeeper scans the ID card and sees the photo:',
    'El vocal escanea el carnet y ve la foto: se acabaron las suplantaciones.' => 'The scorekeeper scans the ID card and sees the photo: no more impersonations.',
    'El vocal escanea este QR en la cancha. La hora en vivo demuestra que no es una captura de pantalla.' => 'The scorekeeper scans this QR at the field. The live clock proves it is not a screenshot.',
    'El vocal marca desde el celular y los hinchas ven el marcador al instante en la página de la liga.' => 'The scorekeeper marks from their phone and fans see the score instantly on the league page.',
    'El vocal registra goles, tarjetas, cambios y reloj desde el celular (funciona aunque se caiga el internet). El público ve el marcador en vivo, se escanea el carnet QR y sale la hoja de vocalía en PDF.' => 'The scorekeeper records goals, cards, substitutions and clock from their phone (it works even if the internet goes down). The public sees the live score, the QR ID card is scanned and the scorekeeping sheet comes out as a PDF.',
    'El árbitro' => 'The referee',
