    'Elegir cuáles incluir →' => 'Choose which to include →',
    'Elija' => 'Choose',
    'Elija Taekwondo, Karate o Judo como deporte del grupo y tendrá: su propia lista de cinturones (kup/dan con puntas), categorías de peso oficiales, poomsae o kata de cada cinturón y exámenes de grado con cobro, acta y certificado con código QR. Está en Alumnos → Exámenes de grado.' => 'Choose Taekwondo, Karate or Judo as the group\'s sport and you get: your own belt list (kup/dan with tips), official weight categories, the poomsae or kata for each belt, and belt exams with fees, exam record and certificate with QR code. It\'s under Students → Belt exams.',
