    'Entre con un clic a cada panel, como si fuera el administrador, el árbitro, el delegado, el vocal o el jugador. Puede probar y guardar lo que quiera: los datos vuelven a estar como nuevos cada madrugada.' => 'Enter each dashboard with one click, as if you were the administrator, referee, delegate, scorekeeper or player. You can try and save whatever you want: the data goes back to new every night.',
