    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el forma de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'This is the list your school uses, in order from first to last. You can change the rank, name, colors, tip and form of each belt, or uncheck the ones you don\'t use. The order determines each student\'s "next belt".',
    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el kata de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'This is the list your school uses, in order from first to last. You can change the rank, name, colors, tip and kata of each belt, or uncheck the ones you don\'t use. The order determines each student\'s "next belt".',
