    'La directiva o la comisión califica al árbitro después de cada partido (nota del {n} al {n}). Si es' => 'The board or the committee rates the referee after each match (score from {n} to {n}). If it is',
    'La edad de cada competidor es la que cumple en este año.' => 'Each competitor\'s age is the age they turn in this year.',
    'La entrada se valida en la puerta con el lector de la liga.' => 'The ticket is validated at the gate with the league\'s scanner.',
