    'La escuela completa: profesores, evaluaciones, tienda y más' => 'The complete school: coaches, evaluations, shop and more',
    'La foto' => 'The photo',
    'La foto siempre se usa en el carnet y en la vocalía para verificar identidad. La cédula completa y los datos del representante nunca se publican.' => 'The photo is always used on the ID card and in the scorekeeping to verify identity. The full ID number and the guardian\'s details are never published.',
    'La inscripción en línea está' => 'Online registration is',
    'La liga de demostración no se cuenta. "Ingreso mensual estimado" = último pago de cada liga pagando dividido para los meses que cubre.' => 'The demo league is not counted. "Estimated monthly income" = last payment of each paying league divided by the months it covers.',
    'La maduración se calcula con la fórmula de Mirwald (talla, talla sentado, peso, edad y género). Dos chicos de la misma edad pueden estar hasta {n} años distintos en su desarrollo: esto ayuda a no descartar a los que maduran tarde y a cuidar la carga de los que están en pleno estirón.' => 'Maturation is calculated with the Mirwald formula (height, sitting height, weight, age and gender). Two boys of the same age can differ by up to {n} years in their development: this helps avoid discarding late developers and manage the load of those in the middle of a growth spurt.',
    'La organización (declara tenerla)' => 'The organization (declares it has it)',
    'La persona' => 'The person',
    'La persona (por su cédula) queda' => 'The person (by their ID number) is',
    'La pestaña' => 'The tab',
    'La plantilla trae las columnas de ese deporte (pareja, peso, grado, vehículo, pruebas…) y en la hoja «Instrucciones» la lista de categorías o pruebas del campeonato.' => 'The template includes the columns for that sport (partner, weight, grade, vehicle, events…) and, in the “Instructions” sheet, the list of the championship\'s categories or events.',
    'La prueba gratis automática está' => 'The automatic free trial is',
    'La página de la liga se actualiza sola:' => 'The league page updates automatically:',
    'La página de la liga se actualiza sola: marcador, minuto y goleadores al instante.' => 'The league page updates automatically: score, minute and top scorers instantly.',
    'La página de la liga y su Resumen muestran los jugadores que cumplen años hoy (con su edad) y los equipos que se acercan a su aniversario (ponga la' => 'The league page and its Overview show the players who have a birthday today (with their age) and the teams approaching their anniversary (enter the',
    'La página de su escuela con su propia dirección (www.suescuela.com) en vez de tuacademia.tukanec.com/su-escuela.' => 'Your school\'s page with its own address (www.suescuela.com) instead of tuacademia.tukanec.com/su-escuela.',
    'La página de verificación del carnet (a la que se llega escaneando el QR) muestra la foto y la cédula parcialmente oculta, solo para identificar al participante.' => 'The ID card verification page (reached by scanning the QR) shows the photo and the partially hidden ID number, only to identify the participant.',
    'La tabla aparece cuando se juegue el primer partido pronosticado.' => 'The table appears once the first predicted match is played.',
    'La ven los padres' => 'Parents can see it',
