    'La vocalía no deja marcar más presentes.' => 'The scorekeeping does not allow marking more players present.',
    'La vocalía sigue funcionando:' => 'The scorekeeping keeps working:',
    'La vocalía sigue funcionando: guarda los goles, tarjetas y presentes en el celular y los envía solos cuando vuelve la señal.' => 'The scorekeeping keeps working: it saves goals, cards and attendance on the phone and sends them automatically when the signal returns.',
