    'Las facturas electrónicas' => 'Electronic invoices',
    'Las familias suben aquí la foto de su transferencia desde su portal. Revise que el dinero llegó y apruébelo: se emite el recibo.' => 'Families upload the photo of their transfer here from their portal. Check that the money arrived and approve it: the receipt is issued.',
    'Las fotos no van en el Excel: se suben después en cada equipo, o las sube cada delegado.' => 'Photos are not included in the Excel file: they are uploaded afterwards for each team, or each delegate uploads them.',
    'Las fotos no van en el Excel: se suben después en la ficha de cada persona. Máximo' => 'Photos are not included in the Excel file: they are uploaded afterwards on each person\'s record. Maximum',
    'Las fotos no van en el Excel: se suben después en la ficha de cada persona. Máximo {n} filas por archivo. También acepta archivos CSV.' => 'Photos do not go in the Excel file: they are uploaded later in each person\'s record. Maximum {n} rows per file. CSV files are also accepted.',
    'Las fotos y los comprobantes no van en el Excel. Para subir datos desde Excel use' => 'Photos and receipts are not included in the Excel file. To upload data from Excel use',
    'Las ligas y escuelas le pagan su suscripción con tarjeta, y sus equipos y familias les pagan a ellas con TuAcademia de intermediario. Reporte y transferencias en' => 'Leagues and schools pay you their subscription by card, and their teams and families pay them with TuAcademia as intermediary. Report and transfers in',
    'Las medidas se toman en' => 'Measurements are taken on',
    'Las mensualidades se generan solas' => 'Monthly fees are generated automatically',
    'Las mensualidades se generan solas, con su fecha de vencimiento, becas y descuento por hermanos.' => 'Monthly fees are generated automatically, with their due date, scholarships and sibling discount.',
    'Las opciones son los goles de esa jornada (en básquet, los triples).' => 'The options are the goals of that matchday (in basketball, the three-pointers).',
    'Las opciones son los jugadores presentes (si la vocalía los marcó) o las dos plantillas.' => 'The options are the players present (if the scorekeeping marked them) or the two squads.',
    'Las reglas vienen llenas con los valores por defecto de la liga. Cámbielas solo si este campeonato es distinto (otra modalidad, otra duración, otro número de árbitros, etc.).' => 'The rules come filled in with the league\'s default values. Change them only if this championship is different (another format, another duration, another number of referees, etc.).',
