    'Le ayudamos a cargar sus equipos y su primer campeonato' => 'We help you load your teams and your first championship',
    'Le faltan' => 'Missing',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Atlético Chimborazo (Liga Demo TuAcademia). Gratis, sin Telegram ni WhatsApp.' => 'You get a phone notification with every goal, the final result and the schedules of Atlético Chimborazo (Liga Demo TuAcademia). Free, no Telegram or WhatsApp needed.',
