    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Leones. Gratis, sin Telegram ni WhatsApp.' => 'You get a phone notification with every goal, the final result and the schedules of Leones. Free, no Telegram or WhatsApp needed.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Pumas. Gratis, sin Telegram ni WhatsApp.' => 'A notification arrives on their phone with every goal, the final result and Pumas\' kickoff times. Free, no Telegram or WhatsApp needed.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Real Cotopaxi. Gratis, sin Telegram ni WhatsApp.' => 'You get a phone notification with every goal, the final result and the schedules of Real Cotopaxi. Free, no Telegram or WhatsApp needed.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Tigres. Gratis, sin Telegram ni WhatsApp.' => 'A notification arrives on their phone with every goal, the final result and Tigres\' kickoff times. Free, no Telegram or WhatsApp needed.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de {s}.' => 'You get a phone notification with every goal, the final score and the schedule of {s}.',
