    'Llene este formulario y la liga queda funcionando con su administrador, su página pública y (si quiere) su primer campeonato. No hay que copiar archivos ni tocar el servidor.' => 'Fill in this form and the league is up and running with its administrator, its public page and (if you wish) its first championship. No need to copy files or touch the server.',
    'Lo asume la liga (el que paga ve el valor exacto; a usted le llega el valor menos la comisión)' => 'Absorbed by the league (the payer sees the exact amount; you receive the amount minus the commission)',
    'Lo básico (Equipos y jugadores con foto, Sorteo y fixture automático (todos contra todos, grupos, ida y vuelta), Llaves eliminatorias automáticas, Tabla de posiciones, goleadores y tarjetas, Suspensiones automáticas y sanciones…) viene en todos los planes. Marque los módulos que trae este plan:' => 'The basics (Teams and players with photos, Automatic draw and fixtures (round robin, groups, home and away), Automatic knockout brackets, Standings, top scorers and cards, Automatic suspensions and sanctions…) come in all plans. Check the modules included in this plan:',
