    'Los avisos NO le están llegando:' => 'You are NOT receiving the notifications:',
    'Los avisos por Telegram no le están llegando' => 'Telegram notifications are not reaching you',
    'Los celulares solo los ve la liga (para entregar premios). No se publican.' => 'Phone numbers are visible only to the league (to deliver prizes). They are not published.',
    'Los cobros de' => 'Charges for',
    'Los competidores se inscriben solos (y pueden pagar con tarjeta). Además: imágenes para redes, hojas para imprimir, resultados en vivo y copiar para la nueva temporada.' => 'Competitors register themselves (and can pay by card). Also: social media images, printable sheets, live results and copy for the new season.',
    'Los comprobantes de' => 'The receipts of',
    'Los datos' => 'The data',
    'Los datos de menores de {n} años se tratan con especial cuidado: su inscripción requiere la autorización y los datos del representante legal, y su foto no se publica sin permiso expreso.' => 'The data of minors under {n} years old is handled with special care: their registration requires the authorization and details of the legal guardian, and their photo is not published without express permission.',
    'Los datos se guardan en' => 'The data is stored in',
    'Los delegados envían desde su portal la foto de su transferencia o depósito. Revise que el dinero llegó a la cuenta y apruébelo: el pago y el recibo se registran solos. Los datos de la cuenta para pagar se escriben en' => 'Delegates send the photo of their transfer or deposit from their portal. Check that the money reached the account and approve it: the payment and the receipt are recorded automatically. The account details for payment are entered in',
    'Los delegados los ven al enviar el comprobante de su transferencia.' => 'Delegates see them when sending the proof of their transfer.',
    'Los delegados piden desde su portal:' => 'Delegates request from their portal:',
    'Los delegados pueden inscribir jugadores hasta' => 'Delegates can register players until',
    'Los delegados pueden pedir pases en línea' => 'Delegates can request transfers online',
    'Los ejercicios de la escuela. El profesor los elige al planificar cada clase y los padres ven en el diario qué ejercicios hizo su hijo.' => 'The school\'s exercises. The coach chooses them when planning each class, and parents see in the log which exercises their child did.',
    'Los equipos no tienen jugadores registrados.' => 'The teams have no registered players.',
    'Los equipos se inscriben por internet y cada delegado registra a sus jugadores.' => 'Teams register over the internet and each delegate registers their players.',
    'Los equipos se inscriben por internet; cada delegado inscribe a sus jugadores, pide pases, reprogramaciones y apelaciones y ve su estado de cuenta.' => 'Teams register over the internet; each delegate registers their players, requests transfers, reschedulings and appeals, and sees their account statement.',
    'Los equipos y los padres pagan con tarjeta desde su celular, el recibo sale solo y usted ve cada pago en su reporte.' => 'Teams and parents pay by card from their phone, the receipt is issued automatically and you see each payment in your report.',
    'Los hinchas adivinan los resultados de los próximos partidos desde la página de la liga y suman puntos.' => 'Fans guess the results of the upcoming matches from the league page and earn points.',
    'Los hinchas pronostican los resultados gratis y compiten en una tabla. Sin apuestas.' => 'Fans predict results for free and compete in a table. No betting.',
    'Los hinchas reciben en el celular cada gol, el resultado y los horarios de su equipo.' => 'Fans receive every goal, the result and their team\'s schedule on their phone.',
    'Los impuestos solo se muestran desglosados en el reporte; consulte con su contador si su liga debe cobrarlos.' => 'Taxes are only shown itemized in the report; consult your accountant about whether your league must charge them.',
    'Los lugares donde entrenan (nombre y dirección).' => 'The places where they train (name and address).',
    'Los límites y módulos se aplican solos a cada liga o escuela según su plan (en la prueba gratis tienen todo). {n} = sin límite. Un precio en {n} = ese período no se ofrece. En Ligas → Editar puede regalar módulos a una liga.' => 'Limits and modules apply automatically to each league or school according to their plan (on the free trial they have everything). {n} = unlimited. A price of {n} = that period is not offered. In Leagues → Edit you can gift modules to a league.',
    'Los manuales de ligas y de escuelas ya están en español, inglés, francés, portugués e italiano, con todo lo nuevo. Elija el idioma con el botón 🌐.' => 'The league and school manuals are now in Spanish, English, French, Portuguese and Italian, with everything new. Choose the language with the 🌐 button.',
    'Los marcadores en vivo se actualizan solos cada {n} segundos.' => 'Live scores update automatically every {n} seconds.',
    'Los módulos, uno por uno' => 'The modules, one by one',
    'Los padres inscriben a sus hijos desde la página de la escuela.' => 'Parents register their children from the school\'s page.',
    'Los padres inscriben a sus hijos por internet y ven asistencia, pagos, recibos, evaluaciones y libreta desde el celular.' => 'Parents register their children online and see attendance, payments, receipts, evaluations and report card from their phone.',
    'Los padres llenan la ficha desde la página de la escuela. Llega a' => 'Parents fill in the form from the school\'s page. It arrives at',
    'Los padres pagan con tarjeta desde su celular y el pago se aplica solo.' => 'Parents pay by card from their phone and the payment is applied automatically.',
    'Los padres pagan con tarjeta desde su celular, el recibo sale solo y usted ve cada pago en su reporte.' => 'Parents pay by card from their phone, the receipt is issued automatically and you see each payment in your report.',
    'Los padres pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA' => 'Parents pay by card; the receipt is issued automatically. TuAcademia transfers to you what was collected minus the card commission (Credit card {n}% + VAT',
    'Los padres pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%). Usted elige si la comisión la asume su organización o el que paga.' => 'Parents pay by card; the receipt is issued automatically. TuAcademia transfers to you what was collected minus the card commission (Credit card {n}% + VAT · Debit card {n}% + VAT · TuAcademia administrative management {n}%). You choose whether your organization absorbs the commission or the payer does.',
    'Los padres pagan las mensualidades con tarjeta de crédito o débito desde su celular; el recibo sale solo y usted ve cada pago en su reporte.' => 'Parents pay monthly fees by credit or debit card from their phone; the receipt is issued automatically and you see each payment in your report.',
    'Los padres pueden ver las fotos' => 'Parents can see the photos',
    'Los padres ven el plan' => 'Parents see the plan',
    'Los pases en línea solo se piden mientras la inscripción de jugadores está' => 'Online transfers can only be requested while player registration is',
    'Los pilotos con «categoría automática» entran a la primera que cumpla su cilindrada y su motor (atmosférico o turbo). Los turbo van a la categoría turbo aunque su cilindrada sea baja.' => 'Drivers with “automatic category” go into the first one that matches their displacement and engine (naturally aspirated or turbo). Turbos go to the turbo category even if their displacement is low.',
    'Los que carga el vocal en vivo aparecen aquí automáticamente.' => 'Those entered live by the scorekeeper appear here automatically.',
    'Los ven las familias en su portal y en los recibos.' => 'Families see them in their portal and on receipts.',
