    'Mientras la persona participe en la escuela y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'For as long as the person participates in the school and then for the time necessary to preserve the sporting history (champions, statistics) and meet legal obligations (for example, accounting and tax). Deletion can be requested at any time (point {n}): in that case the personal data is erased and only the anonymous statistics remain.',
