    'Para cambiarlo en todo el campeonato, use las' => 'To change it for the whole championship, use the',
    'Para campeonatos cortos (relámpago, de verano, de barrio): un solo torneo de hasta 20 equipos durante 3 meses, con casi todos los módulos (el fixture para imprimir y el esquema del campeonato son del plan Profesional).' => 'For short championships (flash, summer, neighborhood): a single tournament of up to 20 teams for 3 months, with almost all modules (printable fixtures and the championship layout are part of the Professional plan).',
    'Para campeonatos cortos (relámpago, de verano, de barrio): un solo torneo de hasta {n} equipos durante {n} meses, con todos los módulos.' => 'For short championships (flash, summer, neighborhood): a single tournament of up to {n} teams for {n} months, with all modules.',
    'Para clubes y academias que compiten con sus categorías (Sub-{n} a Sub-{n}). Agrega:' => 'For clubs and academies that compete with their categories (U-{n} to U-{n}). Adds:',
    'Para clubes y academias:' => 'For clubs and academies:',
    'Para clubes y academias: partidos con convocatoria y minutos jugados, notas del cuerpo técnico por área, valoración del jugador, seguimiento escolar, maduración y pico de crecimiento, y lesiones con fases de regreso. Se activa en Parámetros.' => 'For clubs and academies: matches with squad call-ups and minutes played, coaching staff notes by area, player rating, school follow-up, maturation and growth spurt, and injuries with return phases. Enabled in Settings.',
