    'Para el mismo dueño que tiene una liga y una escuela: los dos planes bajan {n}% y los administradores de esta cuenta pueden pasar a la otra con su mismo usuario ("🔁 Ir a…").' => 'For the same owner who has a league and a school: both plans drop {n}% and this account\'s administrators can switch to the other with the same username ("🔁 Go to…").',
