    'Se copian las reglas de juego, puntos, tarjetas, árbitros, dinero y categoría. No se copian partidos, resultados, sanciones ni el campeón. Las fechas de inscripción en línea quedan cerradas hasta que las ponga.' => 'All rules of play, points, cards, referees, money and category are copied. Matches, results, sanctions and the champion are not copied. Online registration dates remain closed until you set them.',
