    'Suplente' => 'Substitute',
    'Sus campeonatos federativos (inter-ligas) de cualquier deporte se crean en' => 'Your federation (inter-league) championships in any sport are created in',
    'Sus datos' => 'Your details',
    'Sus equipos pagan con tarjeta de crédito o débito desde su celular. TuAcademia recibe el dinero por medio de Plux, aplica el pago y emite el recibo al instante, y le transfiere lo cobrado a su cuenta. Costo: Tarjeta de crédito {n}% + IVA' => 'Your teams pay by credit or debit card from their phones. TuAcademia receives the money through Plux, applies the payment, issues the receipt instantly, and transfers what was collected to your account. Cost: Credit card {n}% + VAT',
    'Sus equipos pagan con tarjeta de crédito o débito desde su celular. TuAcademia recibe el dinero por medio de Plux, aplica el pago y emite el recibo al instante, y le transfiere lo cobrado a su cuenta. Costo: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%.' => 'Your teams pay by credit or debit card from their phones. TuAcademia receives the money through Plux, applies the payment, issues the receipt instantly, and transfers what was collected to your account. Cost: Credit card {n}% + VAT · Debit card {n}% + VAT · TuAcademia administrative fee {n}%.',
    'Sus equipos pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA' => 'Your teams pay by credit or debit card; the receipt is issued automatically and you receive the transfer in your account. Cost per transaction: Credit card {n}% + VAT',
    'Sus equipos pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%. Usted elige si la comisión la asume su organización o el que paga.' => 'Your teams pay by credit or debit card; the receipt is issued automatically and you receive the transfer in your account. Cost per transaction: Credit card {n}% + VAT · Debit card {n}% + VAT · TuAcademia administrative fee {n}%. You choose whether your organization or the payer covers the fee.',
    'Sus equipos pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA' => 'Your teams pay by card; the receipt is issued automatically. TuAcademia transfers to you what was collected minus the card fee (Credit card {n}% + VAT',
    'Sus equipos pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%). Usted elige si la comisión la asume su organización o el que paga.' => 'Your teams pay by card; the receipt is issued automatically. TuAcademia transfers to you what was collected minus the card fee (Credit card {n}% + VAT · Debit card {n}% + VAT · TuAcademia administrative fee {n}%). You choose whether your organization or the payer covers the fee.',
    'Sus equipos pagan inscripciones, arbitrajes y multas con' => 'Your teams pay registrations, refereeing fees and fines with',
    'Sus equipos y familias le pagan con tarjeta de crédito o débito desde su celular; el sistema aplica el pago, emite el recibo y usted ve todo en su reporte de pagos.' => 'Your teams and families pay you by credit or debit card from their phones; the system applies the payment, issues the receipt and you see everything in your payment report.',
    'Sus familias pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA' => 'Your families pay by credit or debit card; the receipt is issued automatically and you receive the transfer in your account. Cost per transaction: Credit card {n}% + VAT',
    'Sus familias pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%. Usted elige si la comisión la asume su organización o el que paga.' => 'Your families pay by credit or debit card; the receipt is issued automatically and you receive the transfer in your account. Cost per transaction: Credit card {n}% + VAT · Debit card {n}% + VAT · TuAcademia administrative fee {n}%. You choose whether your organization or the payer covers the fee.',
    'Sus familias pagan las mensualidades con' => 'Your families pay the monthly fees with',
    'Sus goles y tarjetas anteriores quedan con su equipo anterior. El sistema revisa el cupo y la categoría del equipo que lo recibe.' => 'Their previous goals and cards stay with their previous team. The system checks the squad limit and category of the receiving team.',
    'Sus partidos designados, el informe arbitral y sus honorarios.' => 'Your assigned matches, the referee report and your fees.',
