    'Sí:' => 'Yes:',
    'Sí: cada liga y cada campeonato tienen su dirección corta ({n}:{n}/su-liga/apertura) y, pagando el plan Profesional por {n} año, le damos un dominio propio (www.suliga.com).' => 'Yes: each league and each championship has its own short address ({n}:{n}/your-league/apertura) and, if you pay the Professional plan for {n} year, we give you your own domain (www.yourleague.com).',
    'Sí: fútbol {n}, {n}, {n}, {n}, {n}, {n} o personalizado, indor, ecuavóley por sets y básquet. Cada campeonato define sus jugadores, tiempos, árbitros y reglas.' => 'Yes: {n}-a-side football ({n}, {n}, {n}, {n}, {n} or custom), futsal, set-based ecuavóley and basketball. Each championship defines its players, match times, referees and rules.',
    'Sí: su escuela tiene su dirección corta ({n}:{n}/su-escuela) y, pagando el plan Escuela Completo por {n} año, le damos un dominio propio (www.suescuela.com).' => 'Yes: your school has its own short address ({n}:{n}/your-school) and, if you pay the Complete School plan for {n} year, we give you your own domain (www.yourschool.com).',
