    'Una imagen o captura de ejemplo (opcional)' => 'An example image or screenshot (optional)',
    'Una jornada de evaluación es el día (o la semana) en que se toman los tests a todos. Se crea una vez con los tests elegidos y cada profesor la llena desde el celular en el entrenamiento. Así todos los alumnos quedan medidos con la misma fecha y se comparan con la jornada anterior.' => 'An evaluation session is the day (or week) when everyone takes the tests. It is created once with the chosen tests and each coach fills it in from their phone during training. This way all students are measured on the same date and compared with the previous session.',
