    'Venda espacios a empresas del barrio:' => 'Sell ad space to local businesses:',
    'Venda espacios a empresas del barrio: su banner sale en la página pública de la liga, en los partidos ("Partido presentado por…"), en las imágenes para redes y en los carnets. El sistema cuenta cuántas veces se mostró su marca y cuántos clics recibió: imprima el' => 'Sell ad space to local businesses: their banner appears on the league\'s public page, in matches ("Match presented by…"), in social media images and on ID cards. The system counts how many times your brand was shown and how many clicks it received: print the',
    'Venda las entradas de sus partidos por internet (tarjeta o transferencia), en taquilla y cortesías, con parqueadero opcional. Cada entrada tiene su QR y en la puerta se valida con el celular, aunque no haya internet.' => 'Sell tickets for your matches online (card or transfer), at the box office and as complimentary tickets, with optional parking. Each ticket has its QR and is validated at the gate with a phone, even without internet.',
    'Venda por adelantado las entradas de sus partidos, también a los hinchas. Cada entrada tiene su QR y en la puerta se valida con el celular. Si no marca la casilla, no aparece nada de esto.' => 'Sell tickets for your matches in advance, also to fans. Each ticket has its QR and is validated at the gate with a phone. If you do not check the box, none of this appears.',
