    'En ⭐ Mi plan ahora puede elegir su plan, transferir y subir la foto del comprobante. Lo revisamos y su cuenta queda activa el mismo día; le avisamos por correo y Telegram. Si está en demo, al contratar sigue con todo lo que ya cargó.' => 'In ⭐ My plan you can now choose your plan, transfer and upload the photo of the receipt. We review it and your account is activated the same day; we notify you by email and Telegram. If you are on a demo, when you subscribe you keep everything you already entered.',
