    'gana quien suma más puntos. Límite %: los que llegan más allá de ese porcentaje del tiempo del ganador quedan fuera de control (OTL) y salen de la general (UCI usa entre 8 % y 20 % según la etapa).' => 'the rider with the most points wins. Limit %: riders finishing beyond that percentage of the winner\'s time are outside the time limit (OTL) and leave the GC (UCI uses 8% to 20% depending on the stage).',
    'Ruta:' => 'Road:',
    'escriba el tiempo real de llegada de cada uno; el sistema aplica solo el mismo tiempo del grupo, las bonificaciones de meta, los puntos y el fuera de control según la configuración de cada etapa. En ⚑ cargue las bonificaciones y puntos de los sprints intermedios y los puntos de montaña.' => 'enter each rider\'s real finishing time; the system automatically applies the bunch same time, finish bonuses, points and time limit according to each stage\'s settings. In ⚑ enter intermediate sprint bonuses and points and mountain points.',
    'XCO:' => 'XCO:',
    'en «vueltas» ponga las vueltas que completó; si el comisario lo retiró por la regla del 80 % o fue doblado, ponga su tiempo y sus vueltas (queda clasificado detrás, con «−N vueltas»).' => 'in «laps» enter the laps completed; if the commissaire pulled the rider by the 80% rule or they were lapped, enter their time and laps (they are ranked behind, with «−N laps»).',
