    'Reglas de la UCI: la general suma los tiempos de las etapas menos las bonificaciones; los que llegan en el mismo grupo (menos de 1 s) reciben el mismo tiempo (m.t.). OTL: fuera de control · DNF: no terminó · DSQ: descalificado · DNS: no largó.' => 'UCI rules: the GC adds the stage times minus bonuses; riders in the same group (less than 1 s) get the same time (s.t.). OTL: outside time limit · DNF: did not finish · DSQ: disqualified · DNS: did not start.',
