    '🚴 Ciclismo con las reglas de la UCI' => '🚴 Cycling with UCI rules',
    'Ruta: etapas en línea, contrarreloj y critérium, bonificaciones, mismo tiempo del grupo, fuera de control y clasificaciones de puntos, montaña, mejor joven y equipos. Nuevos deportes: ciclismo de pista (velocidad, keirin, persecución, puntos, scratch, eliminación, tempo y omnium), BMX Racing (motos, cuartos, semis y final), BMX Freestyle (Park y Flatland con jueces) y MTB (cross-country por vueltas, descenso y enduro).' => 'Road: road stages, time trials and criteriums, time bonuses, bunch same time, time limit and points, mountains, best young rider and team classifications. New sports: track cycling (sprint, keirin, pursuit, points, scratch, elimination, tempo and omnium), BMX Racing (motos, quarterfinals, semifinals and final), BMX Freestyle (Park and Flatland with judges) and MTB (cross-country by laps, downhill and enduro).',
