    'El sistema ahora se arma por deporte: Fútbol, Básquet, Vóley, Ecuavóley, Ciclismo, Deportes de combate, Deportes de raqueta, Natación, Atletismo, Bolos y Automovilismo. Agregue a su cuenta los deportes que necesite con descuento desde el segundo módulo; todo queda en el mismo panel. Cada deporte pide sus propios datos y documentos (licencia, certificado médico, peso, grado…).' => 'The system is now built by sport: Football, Basketball, Volleyball, Ecuavolley, Cycling, Combat sports, Racket sports, Swimming, Athletics, Bowling and Motorsport. Add the sports you need to your account with a discount from the second module; everything stays in the same panel. Each sport asks for its own data and documents (licence, medical certificate, weight, grade…).',
    // (v35) módulos separados
    'Deportes de raqueta' => 'Racket sports',
    'Automovilismo' => 'Motorsport',
    'Tenis, pádel y tenis de mesa: llaves con cabezas de serie, marcador por sets, todos contra todos y ranking.' => 'Tennis, padel and table tennis: seeded brackets, set scoring, round robin and ranking.',
    'Pruebas por estilo y distancia (libre, espalda, pecho, mariposa, combinado y relevos), por edad y rama, con medallero y puntos por club.' => 'Events by stroke and distance (freestyle, backstroke, breaststroke, butterfly, medley and relays), by age and gender, with medal table and club points.',
    'Carreras, vallas, saltos, lanzamientos y relevos por categoría y rama, con medallero, puntos por club y mejores marcas.' => 'Running, hurdles, jumps, throws and relays by category and gender, with medal table, club points and best marks.',
    'Jornadas con líneas, handicap automático, récords y clasificación individual y por clubes.' => 'Rounds with games, automatic handicap, records and individual and club standings.',
    'Autocross por mangas con categorías por cilindrada y motor, conos, penalizaciones y campeonato por puntos o tiempo.' => 'Autocross by runs with categories by engine size and type, cones, penalties and championship by points or time.',
