    'Tenis, Pádel, Tenis de mesa, Squash' => 'Tennis, Padel, Table tennis, Squash',
    'Tenis, pádel, tenis de mesa y squash: llaves con cabezas de serie, grupos, consolación, Monrad, escalera del club, marcador por sets o games a 11 y ranking del circuito.' => 'Tennis, padel, table tennis and squash: seeded draws, groups, consolation, Monrad, club ladder, scoring by sets or games to 11 and circuit ranking.',
    'Torneos por sistema suizo (Buchholz), todos contra todos o llave, con ELO, categorías Sub 10 a Sub 18 y ranking del circuito.' => 'Swiss-system (Buchholz), round-robin or knockout tournaments, with ratings, U10 to U18 categories and circuit ranking.',
    'Torneos de videojuegos 1 vs 1 o 2 vs 2 (eFootball, FIFA/FC y otros): grupos, llaves con penales, tabla por goles y ranking.' => 'Video game tournaments 1 vs 1 or 2 vs 2 (eFootball, FIFA/FC and others): groups, draws with penalties, table by goals and ranking.',
    'Competencias con las reglas de la IWF: categorías de peso corporal, 3 intentos de arranque y 3 de envión, total, medallero y puntos por club.' => 'Competitions with IWF rules: bodyweight categories, 3 snatch and 3 clean & jerk attempts, total, medal table and club points.',
    'Triatlón, duatlón y acuatlón: tiempo por segmento y transiciones, clasificación general, por rama y por grupo de edad.' => 'Triathlon, duathlon and aquathlon: time per segment and transitions, overall results, by gender and by age group.',
    'Balonmano (handball) 7 contra 7: goles, goles de 7 metros, exclusiones de 2 minutos, amonestaciones y descalificaciones, vocalía en vivo, tabla 2-1-0 y goleadores.' => 'Handball 7 vs 7: goals, 7-metre goals, 2-minute suspensions, warnings and disqualifications, live scoring, 2-1-0 table and top scorers.',
    'Béisbol (9 entradas) y softbol (7 entradas): carreras por entrada, hits, errores, jonrones y ponches, pizarra del partido, vocalía en vivo y tabla de ganados.' => 'Baseball (9 innings) and softball (7 innings): runs per inning, hits, errors, home runs and strikeouts, line score, live scoring and table of wins.',
    'Pista y campo con las reglas de World Athletics (series y final, viento, concursos con intentos, salto alto y garrocha por alturas, heptatlón y decatlón) y carreras de ruta, trail y cross con tiempo de chip, grupos de edad, diplomas y equipos.' => 'Track and field with World Athletics rules (heats and final, wind, field events with attempts, high jump and pole vault by heights, heptathlon and decathlon) and road, trail and cross-country races with chip timing, age groups, certificates and teams.',
    'Squash · Games a 11: grupos y luego llave, Monrad con todos los puestos, escalera del club y ranking.' => 'Squash · Games to 11: groups then draw, Monrad with all places, club ladder and ranking.',
    'Ajedrez · Sistema suizo con Buchholz, ELO y todos contra todos.' => 'Chess · Swiss system with Buchholz, ratings and round robin.',
    'E-sports · eFootball 1 vs 1: grupos, llave con penales y tercer puesto.' => 'E-sports · eFootball 1 vs 1: groups, draw with penalties and third place.',
    'Carreras de ruta, trail y cross · 10K con tiempo de chip, grupos de edad, equipos, buscador por dorsal y diplomas.' => 'Road, trail and cross-country races · 10K with chip timing, age groups, teams, bib search and certificates.',
    'Levantamiento de pesas · Arranque y envión con 3 intentos, total y peso corporal (IWF).' => 'Weightlifting · Snatch and clean & jerk with 3 attempts, total and bodyweight (IWF).',
    'Triatlón · Natación, transiciones, ciclismo y carrera, con grupos de edad.' => 'Triathlon · Swim, transitions, bike and run, with age groups.',
