    'Grupos de 3 a 5 (todos contra todos) y los primeros de cada grupo pasan a una llave final. Es el formato de los nacionales de squash.' => 'Groups of 3 to 5 (round robin); the top players of each group go to a final draw. It is the format of squash nationals.',
