    'Nadie queda fuera: ganadores y perdedores siguen jugando en sub-llaves hasta definir todos los puestos (1.º al último).' => 'Nobody is out: winners and losers keep playing in sub-draws until every place is decided (1st to last).',
    'Por rondas: en cada ronda se empareja a los de igual puntaje sin repetir rival. Ideal para ajedrez y para muchos inscritos.' => 'By rounds: each round pairs players with the same score without repeating opponents. Ideal for chess and many entrants.',
