    'Concurso (World Athletics)' => 'Field event (World Athletics)',
    'en cada intento escriba la marca en metros (ej:' => 'for each attempt write the mark in metres (e.g.',
    'si fue nulo o' => 'if it was a foul or',
    'si pasó. Gana la mejor marca; si empatan, decide la segunda mejor.' => 'if passed. The best mark wins; on a tie, the second best decides.',
    'si pasó. Después de {n} intentos, los {n} mejores hacen {n} más (sus casillas se marcan en verde). Gana la mejor marca; si empatan, decide la segunda mejor.' => 'if passed. After {n} attempts, the best {n} get {n} more (their boxes turn green). The best mark wins; on a tie, the second best decides.',
    'si pasó. Después de {n} intentos, los {n} mejores hacen {n} más (sus casillas se marcan en verde). Gana la mejor marca; si empatan, decide la segunda mejor. Debajo de cada marca, el viento (ej: +{n}).' => 'if passed. After {n} attempts, the best {n} get {n} more (their boxes turn green). The best mark wins; on a tie, the second best decides. Below each mark, the wind (e.g. +{n}).',
    'Salto alto y garrocha (World Athletics)' => 'High jump and pole vault (World Athletics)',
    'en cada altura escriba lo que hizo:' => 'at each height write what happened:',
    'pasó al {n}.º,' => 'cleared on the {n}st,',
    'al {n}.º,' => 'on the {n}nd/{n}rd,',
    'quedó eliminado,' => 'eliminated,',
    'y luego pasó a la siguiente (' => 'and then moved on to the next height (',
    'si no saltó esa altura. Gana la mayor altura; si empatan, el de menos intentos en esa altura y luego el de menos fallos en todo el concurso.' => 'if the height was not attempted. The highest height wins; on a tie, fewer attempts at that height, then fewer failures in the whole competition.',
    'Heptatlón (tabla de puntos de World Athletics)' => 'Heptathlon (World Athletics scoring tables)',
    'Decatlón (tabla de puntos de World Athletics)' => 'Decathlon (World Athletics scoring tables)',
    'escriba la marca de cada prueba: tiempos como' => 'write the mark of each event: times like',
    'saltos y lanzamientos en metros (' => 'jumps and throws in metres (',
    '). Los puntos se calculan solos y gana el que suma más.' => '). Points are calculated automatically and the highest total wins.',
    'Pesas (IWF)' => 'Weightlifting (IWF)',
    'escriba el peso corporal del pesaje y los kilos de cada intento:' => 'write the bodyweight at the weigh-in and the kilos of each attempt:',
    'escriba el peso corporal del pesaje (hasta {n} kg) y los kilos de cada intento:' => 'write the bodyweight at the weigh-in (up to {n} kg) and the kilos of each attempt:',
    'escriba el peso corporal del pesaje (más de {n} kg) y los kilos de cada intento:' => 'write the bodyweight at the weigh-in (over {n} kg) and the kilos of each attempt:',
    'si fue válido,' => 'if good,',
    'si fue nulo,' => 'if no lift,',
    'si no lo hizo. Cada intento debe ser igual o mayor que el anterior. Total = mejor arranque + mejor envión; si empatan, gana el de menor peso corporal.' => 'if not attempted. Each attempt must be equal to or higher than the previous one. Total = best snatch + best clean & jerk; on a tie, the lighter lifter wins.',
    'Por segmentos' => 'By segments',
    'escriba el tiempo de cada parte (ej:' => 'write the time of each segment (e.g.',
    '). El total se suma solo; solo clasifica quien tiene todos los segmentos. Grupos de edad: {s}.' => '). The total adds up automatically; only athletes with every segment are ranked. Age groups: {s}.',
