    '(chip, desde que cruzó la salida). Clasifica por tiempo oficial. Grupos de edad: {s} (por rama). Por equipos suman los {s} primeros de cada club.' => '(chip, from crossing the start line). Ranked by official time. Age groups: {s} (by gender). Team score adds the first {s} of each club.',
    'Por pruebas ({n} m libre, {n} m planos, salto largo, velocidad, keirin, omnium, BMX, park...) separadas por categoría de edad y rama. Se cargan los tiempos, distancias, puestos o notas y el sistema arma los resultados de cada prueba con las reglas de cada deporte (en ciclismo, las de la UCI), el' => 'By events ({n} m freestyle, {n} m sprint, long jump, sprint, keirin, omnium, BMX, park...) split by age category and gender. Enter the times, distances, places or scores and the system builds the results of each event with each sport\'s rules (in cycling, the UCI\'s), the',
