    'El total que paga el cliente = precio del plan (Básico, Profesional…) + lo de esta columna. En {n} y {n} meses se aplica la misma rebaja del plan (meses gratis).' => 'The customer\'s total = plan price (Basic, Professional…) + this column. For {n} and {n} months the plan\'s same discount applies (free months).',
    'Son los valores con los que empieza cada campeonato nuevo de este deporte en todas las cuentas. Deje vacío para usar el valor de fábrica (entre paréntesis). Cada cuenta puede cambiarlos después en su campeonato.' => 'These are the values every new championship of this sport starts with in all accounts. Leave blank to use the factory value (in brackets). Each account can change them later in its championship.',
    '— de fábrica —' => '— factory —',
    'Nombre, cédula, foto, fecha de nacimiento y club ya están en cada ficha: aquí van los datos propios del deporte.' => 'Name, ID, photo, date of birth and club are already on every profile: here go the sport\'s own fields.',
    'Nuevo documento (ej: Ficha de la federación)' => 'New document (e.g. Federation form)',
    'Para quitar un documento, borre su nombre. Con «tiene vencimiento» se pide la fecha y, cuando pasa, vuelve a aparecer como faltante (ej: certificado médico anual).' => 'To remove a document, delete its name. With “expires” the date is requested and, once passed, it shows as missing again (e.g. yearly medical certificate).',
    'Se piden en la ficha del jugador, del competidor o del alumno de este deporte y en la inscripción en línea. Lo' => 'They are requested on the player, competitor or student profile for this sport and in online registration. Anything',
    'que falte aparece como «⚠ falta» en las listas, y en la inscripción en línea no se puede enviar sin eso.' => 'missing shows as “⚠ missing” in the lists, and online registration cannot be sent without it.',
    'Para que el panel siga funcionando sin interrupciones, renueve antes de esa fecha.' => 'To keep the panel running without interruption, renew before that date.',
    '⏰ Su suscripción de TuAcademia vence en {s} días ({s})' => '⏰ Your TuAcademia subscription expires in {s} days ({s})',
    'Activa hasta el {s} (faltan {s} días)' => 'Active until {s} ({s} days left)',
    'Puede crear {n} campeonato a la vez (en curso) · lleva {n} · no le quedan más' => 'You can run {n} championship at a time (in progress) · you have {n} · none left',
    'El sistema se vende por deporte. Cada cuenta tiene sus módulos; quien compra más de uno lo ve todo junto en el mismo panel. Aquí maneja precios, requisitos, reglas por defecto, qué módulos tiene cada cuenta y las demos de cada deporte.' => 'The system is sold by sport. Each account has its modules; whoever buys more than one sees everything together in the same panel. Here you manage prices, requirements, default rules, which modules each account has and each sport\'s demos.',
    '(natación, atletismo, ciclismo de pista, bmx racing, bmx freestyle, carreras de ruta, trail y cross, levantamiento de pesas, triatlón, duatlón y acuatlón)' => '(swimming, athletics, track cycling, BMX racing, BMX freestyle, road, trail and cross-country running, weightlifting, triathlon, duathlon and aquathlon)',
    '(tenis, pádel, tenis de mesa, squash, artes marciales, boxeo, ajedrez, e-sports)' => '(tennis, padel, table tennis, squash, martial arts, boxing, chess, e-sports)',
