    'Varones Libre' => 'Men Open',
    'Precios en dólares. En la demo tiene todos los módulos (el fixture para imprimir y el esquema del campeonato son exclusivos del plan Profesional). ¿Necesita algo especial? Consúltenos.' => 'Prices in US dollars. The demo has every module (the printable fixture and the championship diagram are exclusive to the Professional plan). Need something special? Ask us.',
    '· 🎓 Escuela multideporte (fútbol, básquet, vóley, boxeo, natación, taekwondo y tenis) ·' => '· 🎓 Multi-sport school (football, basketball, volleyball, boxing, swimming, taekwondo and tennis) ·',
