    'Fútbol, indor, vóley, ecuavóley, básquet, balonmano, béisbol y deportes individuales: carreras, tenis, pádel, squash, tenis de mesa, artes marciales, boxeo, ajedrez, e-sports, bolos, natación, atletismo, carreras de ruta, pesas y triatlón; y olimpiadas multideportivas.' => 'Football, futsal, volleyball, ecuavolley, basketball, handball, baseball and individual sports: races, tennis, padel, squash, table tennis, martial arts, boxing, chess, e-sports, bowling, swimming, athletics, road running, weightlifting and triathlon; and multi-sport olympics.',
