    '(v{n}) Nota del dominio incluido (sale con * en los planes)' => '(v{n}) Included-domain note (shown with * in the plans)',
    '* El dominio propio viene incluido al pagar el plan por {n} año. El dominio es propiedad de tupass.com; la organización lo usa mientras mantenga su plan al día.' => '* The own domain is included when paying the plan for {n} year. The domain belongs to tupass.com; the organization uses it while its plan is up to date.',
    '* El dominio propio viene incluido al pagar el plan por {n} año. La academia lo usa mientras mantenga su plan al día.' => '* The own domain is included when paying the plan for {n} year. The academy uses it while its plan is up to date.',
    'Desde ${n} al mes. Puede pagar mensual, semestral (ahorra {n} mes) o anual (ahorra {n} meses), por transferencia o con tarjeta. Primero le preparamos una demo para que lo conozca.' => 'From ${n} per month. You can pay monthly, semiannually (save {n} month) or yearly (save {n} months), by bank transfer or card. First we prepare a demo so you can get to know it.',
    'Desde ${n} por {n} meses. Puede pagar mensual, semestral (ahorra {n} mes) o anual (ahorra {n} meses), por transferencia o con tarjeta. Primero le preparamos una demo para que lo conozca.' => 'From ${n} for {n} months. You can pay monthly, semiannually (save {n} month) or yearly (save {n} months), by bank transfer or card. First we prepare a demo so you can get to know it.',
    'en cada plan. Se mantiene el ahorro de {n} mes en el semestre y de {n} meses en el año.' => 'in each plan. You still save {n} month on the semiannual plan and {n} months on the annual plan.',
