    'Guardar funciones y precios' => 'Save features and prices',
    'Lo básico (equipos, campeonatos, alumnos, pagos con recibo, página pública…) lo tiene todo cliente. Cada función de aquí se cobra aparte si no está en su plan. Qué trae cada plan se cambia en' => 'Every client has the basics (teams, championships, students, payments with receipt, public page…). Each feature here is charged separately if it is not in their plan. What each plan includes is changed in',
    '. Lo encendido de cada cliente, en Ligas → Editar → Módulos de la cuenta. Apagar nunca borra datos.' => '. What is on for each client, in Leagues → Edit → Account modules. Turning off never deletes data.',
    'Los clientes los piden desde ⭐ Mi plan. También llegan al Panel Tukán Central (Solicitudes → «Cambio de módulos»).' => 'Clients request them from ⭐ My plan. They also reach the Tukán Central Panel (Requests → «Module change»).',
    'No hay pedidos.' => 'There are no requests.',
    'Crear demo' => 'Create demo',
    'En ⭐ Mi plan → Mis módulos ve las funciones que tiene encendidas y las que puede agregar, con su precio. Toque «Pedir este módulo» y se lo encendemos (normalmente el mismo día). Si un módulo se apaga, sus datos no se borran.' => 'In ⭐ My plan → My modules you see the features you have on and the ones you can add, with their price. Tap «Request this module» and we turn it on (usually the same day). If a module is turned off, your data is not deleted.',
    'en la prueba gratis tienen todo' => 'in the demo they have everything',
    // (Anexo B, 18 oct 2026) módulos por cliente y «todo se pide demo» (sin prueba gratis)
    '${n} (ahorra {n} meses) + dominio incluido' => '${n} (save {n} months) + domain included',
    'Nombre, disciplinas, pensión y listo (pida su demo y la preparamos con usted).' => 'Name, disciplines, fee and done (request your demo and we set it up with you).',
    'Precios en dólares. En la demo tiene todo. ¿Necesita algo especial? Consúltenos.' => 'Prices in US dollars. In the demo you have everything. Need something special? Ask us.',
    'Desde ${n} al mes. Puede pagar mensual, semestral (paga {n} meses y recibe {n}) o anual (paga {n} y recibe {n}, más dominio propio). Primero le preparamos una demo.' => 'From ${n} per month. You can pay monthly, semiannually (pay {n} months, get {n}) or yearly (pay {n}, get {n}, plus your own domain). First we prepare a demo for you.',
    // (20 oct 2026) sin «gratis»: textos nuevos
    'Sin costo' => 'No cost',
    'Sin costo y sin apuestas' => 'No cost and no betting',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Atlético Chimborazo (Liga Demo TuAcademia). No necesita Telegram ni WhatsApp.' => 'You get a phone notification with every goal, the final result and the schedules of Atlético Chimborazo (Liga Demo TuAcademia). No Telegram or WhatsApp needed.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Atlético Chimborazo. No necesita Telegram ni WhatsApp.' => 'You get a phone notification with every goal, the final result and the schedules of Atlético Chimborazo. No Telegram or WhatsApp needed.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Deportivo Los Andes (Liga Demo TuAcademia). No necesita Telegram ni WhatsApp.' => 'You get a phone notification with every goal, the final result and the schedules of Deportivo Los Andes (Liga Demo TuAcademia). No Telegram or WhatsApp needed.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Deportivo Los Andes. No necesita Telegram ni WhatsApp.' => 'You get a phone notification with every goal, the final result and the schedules of Deportivo Los Andes. No Telegram or WhatsApp needed.',
