    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Leones. No necesita Telegram ni WhatsApp.' => 'You get a phone notification with every goal, the final result and the schedules of Leones. No Telegram or WhatsApp needed.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Pumas. No necesita Telegram ni WhatsApp.' => 'A notification arrives on their phone with every goal, the final result and Pumas\' kickoff times. No Telegram or WhatsApp needed.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Real Cotopaxi. No necesita Telegram ni WhatsApp.' => 'You get a phone notification with every goal, the final result and the schedules of Real Cotopaxi. No Telegram or WhatsApp needed.',
